import {RESEARCH_BRANCHES} from './rules.js';
export const BELIEFS={commons:'Kebersamaan',liberty:'Kebebasan',authority:'Otoritas',technology:'Teknologi',ecology:'Ekologi'};
const clamp=v=>Math.max(0,Math.min(100,v));
function code(seed,id,i){let n=(seed^Math.imul(id*11+i,2654435761))>>>0;return (Math.imul(n^(n>>>15),2246822507)>>>0)%101;}
export function initIdeology(s,a){if(a.ideology)return;const parents=s.agents.filter(p=>p.id!==a.id&&p.alive&&p.age>=18&&p.age<=45&&p.ideology);a.ideology=Object.fromEntries(Object.keys(BELIEFS).map((k,i)=>[k,clamp(a.origin==='birth'&&parents.length>=2?(parents[0].ideology[k]+parents[1].ideology[k])/2+code(s.seed,a.id,i)%21-10:code(s.seed,a.id,i))]));}
export function ideologyName(a){const b=a.ideology,parts=[b.commons>=55?'Komunal':'Individual',b.authority>b.liberty?'Otoriter':'Libertarian',b.technology>b.ecology?'Teknosentris':'Ekosentris'];return parts.join(' · ');}
export function ideologyBonus(a,key){const b=a.ideology;if(!b)return 0;return ['share','teach','treat','heal'].includes(key)?b.commons/80:['defend','govern'].includes(key)?b.authority/90:['explore','diplomacy'].includes(key)?b.liberty/90:['research','craft','makeVehicle'].includes(key)?b.technology/80:['farm','restore','forage'].includes(key)?b.ecology/100:0;}
export function reinforceBeliefs(a,key,reward){if(reward<=0)return;const dim=['share','teach','heal','treat'].includes(key)?'commons':['research','craft','makeVehicle'].includes(key)?'technology':key==='restore'?'ecology':key==='govern'?'authority':key==='diplomacy'?'liberty':null;if(dim)a.ideology[dim]=clamp(a.ideology[dim]+.025);}
export function branchAffinity(a,branch){const b=a.ideology;return ({magic:a.arcaneSensitivity/100,mechanical:b.technology/100,biotic:(a.attributes.endurance+b.ecology)/200,bioengineering:(b.technology+b.ecology)/200,mental:a.attributes.discipline/100,environment:b.ecology/100,warfare:b.authority/100,social:b.commons/100,diplomatic:b.liberty/100,government:(b.authority+b.commons)/200})[branch]||0;}
export function profession(s,a,c=s._context?.civ||s.world?.settlements[0]){const has=id=>c?.discoveries.includes(id);if(a.journey)return a.journey.kind==='campaign'?'Personel militer lapangan':a.journey.kind==='explore'?'Penjelajah':'Pekerja pengumpulan';if(a.age<16)return 'Pelajar';if(a.action==='research'||a.action==='studyMagic')return 'Peneliti '+(RESEARCH_BRANCHES[a.researchBranch]?.name||'umum');if(['wood','stone','mineOre','extract','forage','fish'].includes(a.action))return has('automation')?'Operator lapangan':has('mechanics')?'Operator sumber daya':'Pekerja pengumpulan';if(a.action==='farm')return has('genetics')?'Operator pertanian hayati':'Pekerja pertanian';if(['craft','forgeWeapon','makeVehicle','build'].includes(a.action))return has('precisionEngineering')?'Teknisi produksi':'Perajin';if(['smelt','fuel','alloy','generate','assembleShip'].includes(a.action))return has('automation')?'Teknisi industri':'Operator industri';if(['heal','treat'].includes(a.action))return has('regenerativeMedicine')?'Tenaga medis':'Perawat';if(['diplomacy','translate'].includes(a.action))return 'Petugas diplomasi';if(['defend'].includes(a.action))return has('militaryLogistics')?'Personel militer':'Penjaga';if(a.action==='govern')return 'Petugas pemerintahan';return 'Warga';}
